import math


class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        # Store balances in cents to prevent floating point inaccuracies
        self._balances: dict[str, int] = {m: 0 for m in self.members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if payer not in self._balances:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            parts = list(self.members)
        else:
            parts = list(participants)

        if not parts:
            return

        for p in parts:
            if p not in self._balances:
                raise ValueError(f"Participant '{p}' is not a group member.")

        total_cents = round(amount * 100)
        n = len(parts)

        # Requirement 1: Every other participant owes exactly the amount rounded down to the cent.
        # Leftover cents are borne by the payer.
        base_split = math.floor(total_cents / n)

        for p in parts:
            if p != payer:
                self._balances[p] -= base_split
                self._balances[payer] += base_split

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: self._balances[m] / 100.0 for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Greedy settlement guarantees at most (N - 1) transactions.
        # Debtors have negative balance, creditors have positive balance.
        debtors: list[list] = []
        creditors: list[list] = []

        for m in self.members:
            bal = self._balances[m]
            if bal < 0:
                debtors.append([m, -bal])
            elif bal > 0:
                creditors.append([m, bal])

        payments: list[tuple[str, str, float]] = []

        d_idx = 0
        c_idx = 0

        while d_idx < len(debtors) and c_idx < len(creditors):
            debtor, d_bal = debtors[d_idx]
            creditor, c_bal = creditors[c_idx]

            transfer = min(d_bal, c_bal)

            # Requirement 2: Never propose a payment smaller than 1.00 (100 cents);
            # debts below 1.00 are written off and not included in proposed payments.
            if transfer >= 100:
                payments.append((debtor, creditor, transfer / 100.0))

            debtors[d_idx][1] -= transfer
            creditors[c_idx][1] -= transfer

            if debtors[d_idx][1] == 0:
                d_idx += 1
            if creditors[c_idx][1] == 0:
                c_idx += 1

        return payments
